import { useCallback } from 'react';

import { getFiltersToReset } from 'components/Filter/utils/filterDependencies';
import { usePageFilterData, usePageFilterManagement } from 'hooks';
import { shouldSkipCommercialResultsFormCascade } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsFormCascade';

export const useQuickFilterReset = (pageName: string, fieldKey: string) => {
  const { defaults } = usePageFilterData(pageName);
  const { updateQuickFiltersForm, applyQuickFilters, switchKpi } =
    usePageFilterManagement(pageName);

  const handleClear = useCallback(() => {
    const defaultValue = defaults?.[fieldKey];

    if (fieldKey === 'kpis' && switchKpi && defaultValue != null) {
      switchKpi(String(defaultValue), true);
      return;
    }

    const filtersToReset = shouldSkipCommercialResultsFormCascade(
      pageName,
      fieldKey,
    )
      ? [fieldKey]
      : getFiltersToReset(fieldKey);

    const keysToReset = filtersToReset.length > 0 ? filtersToReset : [fieldKey];

    keysToReset.forEach((key) => {
      updateQuickFiltersForm(key, defaults?.[key]);
    });

    applyQuickFilters();
  }, [
    pageName,
    fieldKey,
    defaults,
    updateQuickFiltersForm,
    applyQuickFilters,
    switchKpi,
  ]);

  return { handleClear };
};
